import type { AppData, CategoryId, CategorySettings, LogEntry, PenaltyRule, StatusLevel } from '../types';
import { CATEGORY_IDS } from './categories';
import { dayKeyOf, daysInMonthKey, monthKeyOf, parseMonthKey, shiftMonthKey, weekRange } from './dates';

export type MonthResult = 'met' | 'exact' | 'over';

export interface MonthCategoryLedger {
  monthKey: string;
  category: CategoryId;
  base: number;
  baseOverridden: boolean;
  /** Penalty the rules would apply to this month (generated by previous month). */
  autoApplied: number;
  /** Penalty actually applied to this month (override ?? auto). */
  applied: number;
  appliedOverridden: boolean;
  effective: number;
  used: number;
  excess: number;
  /** Penalty the rules generate from this month for next month. */
  generatedAuto: number;
  /** Penalty that will actually apply to next month (next month override ?? generatedAuto). */
  nextApplied: number;
  nextOverridden: boolean;
  result: MonthResult;
}

export type Ledger = Record<string, Record<CategoryId, MonthCategoryLedger>>;

export function penaltyFromRule(rule: PenaltyRule, excess: number): number {
  if (excess <= 0) return 0;
  if (rule.mode === 'fixed') return Math.max(0, rule.fixedAmount);
  return Math.max(0, Math.ceil(excess * rule.multiplier - 1e-9));
}

export function describeRule(rule: PenaltyRule, singular: string): string {
  if (rule.mode === 'fixed') return `קנס קבוע: ${rule.fixedAmount} בכל חודש עם חריגה`;
  return `כל ${singular} חריגה = ${rule.multiplier} פחות בחודש הבא`;
}

function readOverride(map: AppData['penaltyOverrides'], key: string, cat: CategoryId): number | undefined {
  const v = map[key]?.[cat];
  return typeof v === 'number' && Number.isFinite(v) ? v : undefined;
}

export function countLogsByMonth(logs: LogEntry[]): Map<string, Record<CategoryId, number>> {
  const out = new Map<string, Record<CategoryId, number>>();
  for (const log of logs) {
    const key = monthKeyOf(log.timestamp);
    let row = out.get(key);
    if (!row) {
      row = { cigarettes: 0, joints: 0, cigars: 0 };
      out.set(key, row);
    }
    row[log.category] += 1;
  }
  return out;
}

/** Ordered list of month keys spanning all data plus the current month. */
export function monthSpan(data: AppData, now: Date): string[] {
  const current = monthKeyOf(now);
  const keys = new Set<string>([current]);
  for (const l of data.logs) keys.add(monthKeyOf(l.timestamp));
  for (const k of Object.keys(data.penaltyOverrides)) keys.add(k);
  for (const k of Object.keys(data.baseBudgetOverrides)) keys.add(k);
  const sorted = [...keys].sort();
  const first = sorted[0] ?? current;
  const last = sorted[sorted.length - 1] ?? current;
  const out: string[] = [];
  let k = first;
  // Safety bound: 50 years of months
  for (let i = 0; i < 600 && k <= last; i += 1) {
    out.push(k);
    k = shiftMonthKey(k, 1);
  }
  return out;
}

/** Forward-computes the full penalty/budget chain month by month. */
export function buildLedger(data: AppData, now: Date): Ledger {
  const months = monthSpan(data, now);
  const counts = countLogsByMonth(data.logs);
  const ledger: Ledger = {};
  const prevGenerated: Record<CategoryId, number> = { cigarettes: 0, joints: 0, cigars: 0 };

  months.forEach((key, idx) => {
    const nextKey = shiftMonthKey(key, 1);
    const row = {} as Record<CategoryId, MonthCategoryLedger>;
    for (const cat of CATEGORY_IDS) {
      const settings = data.settings[cat];
      const baseOv = readOverride(data.baseBudgetOverrides, key, cat);
      const base = baseOv ?? settings.monthlyLimit;
      const autoApplied = idx === 0 ? 0 : prevGenerated[cat];
      const appliedOv = readOverride(data.penaltyOverrides, key, cat);
      const applied = appliedOv ?? autoApplied;
      const effective = Math.max(0, base - applied);
      const used = counts.get(key)?.[cat] ?? 0;
      const excess = Math.max(0, used - effective);
      const generatedAuto = penaltyFromRule(settings.penalty, excess);
      const nextOv = readOverride(data.penaltyOverrides, nextKey, cat);
      row[cat] = {
        monthKey: key,
        category: cat,
        base,
        baseOverridden: baseOv !== undefined,
        autoApplied,
        applied,
        appliedOverridden: appliedOv !== undefined,
        effective,
        used,
        excess,
        generatedAuto,
        nextApplied: nextOv ?? generatedAuto,
        nextOverridden: nextOv !== undefined,
        result: used > effective ? 'over' : used === effective && effective > 0 ? 'exact' : 'met',
      };
      prevGenerated[cat] = generatedAuto;
    }
    ledger[key] = row;
  });
  return ledger;
}

export function dailyBudgetFor(settings: CategorySettings, effective: number, daysInMonth: number): {
  value: number;
  auto: number;
  overridden: boolean;
} {
  const auto = daysInMonth > 0 ? effective / daysInMonth : 0;
  const overridden = settings.dailyOverride !== null;
  return { value: settings.dailyOverride ?? auto, auto, overridden };
}

export interface CategoryStatus {
  category: CategoryId;
  level: StatusLevel;
  headline: string;
  effective: number;
  used: number;
  remaining: number;
  daysInMonth: number;
  dayOfMonth: number;
  dailyBudget: number;
  dailyAuto: number;
  dailyOverridden: boolean;
  allowedUntilToday: number;
  /** allowedUntilToday − used (positive = saved from clean days) */
  bank: number;
  todayCount: number;
  weekCount: number;
  weekStart: Date;
  weekEnd: Date;
  dailyExceeded: boolean;
  daily: { level: StatusLevel; text: string };
  general: { level: StatusLevel; text: string };
  weekly: { level: StatusLevel; text: string } | null;
}

export function formatNum(n: number): string {
  if (Number.isInteger(n)) return String(n);
  return n.toFixed(n < 1 ? 2 : 1).replace(/\.?0+$/, '');
}

export function computeStatus(
  data: AppData,
  ledger: Ledger,
  cat: CategoryId,
  now: Date,
): CategoryStatus {
  const settings = data.settings[cat];
  const key = monthKeyOf(now);
  const row = ledger[key]?.[cat];
  const effective = row?.effective ?? settings.monthlyLimit;
  const used = row?.used ?? 0;
  const daysInMonth = daysInMonthKey(key);
  const dayOfMonth = now.getDate();
  const daily = dailyBudgetFor(settings, effective, daysInMonth);
  const allowedUntilToday = (effective / daysInMonth) * dayOfMonth;
  const bank = allowedUntilToday - used;
  const todayKey = dayKeyOf(now);
  const { start: weekStart, end: weekEnd } = weekRange(now);
  let todayCount = 0;
  let weekCount = 0;
  for (const l of data.logs) {
    if (l.category !== cat) continue;
    if (dayKeyOf(l.timestamp) === todayKey) todayCount += 1;
    if (l.timestamp >= weekStart.getTime() && l.timestamp <= weekEnd.getTime()) weekCount += 1;
  }
  const remaining = effective - used;
  const dailyExceeded = settings.focus === 'daily' && todayCount > daily.value + 1e-9;
  const withinPace = used <= allowedUntilToday + 1e-9;

  // ---- Weekly indicator ----
  let weekly: CategoryStatus['weekly'] = null;
  if (settings.weeklyEnabled) {
    if (weekCount > settings.weeklyLimit) {
      weekly = { level: 'bad', text: `חריגה מהתקציב השבועי (${weekCount}/${settings.weeklyLimit})` };
    } else if (weekCount === settings.weeklyLimit) {
      weekly = { level: 'warning', text: `ניצלת את המכסה השבועית (${weekCount}/${settings.weeklyLimit})` };
    } else {
      weekly = { level: 'good', text: `בתוך התקציב השבועי (${weekCount}/${settings.weeklyLimit})` };
    }
  }

  // ---- Daily indicator ----
  let dailyInd: CategoryStatus['daily'];
  if (dailyExceeded) {
    dailyInd = {
      level: withinPace ? 'warning' : 'bad',
      text: `חריגה מהתקציב היומי (${todayCount}/${formatNum(daily.value)})`,
    };
  } else if (todayCount > 0 && Math.abs(todayCount - daily.value) < 1e-9) {
    dailyInd = { level: 'warning', text: `בדיוק בתקציב היומי (${todayCount}/${formatNum(daily.value)})` };
  } else {
    dailyInd = { level: 'good', text: `בתוך התקציב היומי (${todayCount}/${formatNum(daily.value)})` };
  }

  // ---- General (monthly) indicator & overall level ----
  const criticalPace = used > allowedUntilToday + Math.max(2, effective * 0.25);
  let level: StatusLevel;
  let headline: string;
  let general: CategoryStatus['general'];

  if (used > effective) {
    level = 'bad';
    headline = 'חריגה מהתקציב החודשי';
    general = { level: 'bad', text: `חרגת ב-${used - effective} מהתקציב החודשי` };
  } else if (weekly?.level === 'bad') {
    level = 'bad';
    headline = 'חריגה מהתקציב השבועי';
    general = { level: 'warning', text: 'החודש עדיין בתקציב, אבל השבוע חרגת' };
  } else if (used === effective && effective > 0) {
    level = 'warning';
    headline = 'בדיוק על הגבול החודשי';
    general = { level: 'warning', text: 'ניצלת את כל התקציב החודשי — כל יחידה נוספת היא חריגה' };
  } else if (effective === 0 && used === 0) {
    level = 'good';
    headline = 'חודש נקי';
    general = { level: 'good', text: 'התקציב החודשי הוא 0 — ואתה עומד בו' };
  } else if (settings.focus === 'daily' && criticalPace) {
    level = 'bad';
    headline = 'קצב גבוה מאוד';
    general = { level: 'bad', text: `עישנת ${used} מתוך ${formatNum(allowedUntilToday)} המותרים עד היום` };
  } else if (settings.focus !== 'monthly' && !withinPace) {
    level = 'warning';
    headline = 'קצב מהיר מהמתוכנן';
    general = {
      level: 'warning',
      text: `מעל הקצב: ${used} מתוך ${formatNum(allowedUntilToday)} המותרים עד היום`,
    };
  } else if (dailyExceeded) {
    level = 'warning';
    headline = 'חריגה יומית — מכוסה מהבנק';
    general = { level: 'good', text: 'המצב הכללי בסדר גמור (בזכות ימים נקיים קודמים)' };
  } else if (weekly?.level === 'warning') {
    level = 'warning';
    headline = 'המכסה השבועית נוצלה';
    general = { level: 'good', text: 'המצב החודשי תקין — שמור על השבוע' };
  } else {
    level = 'good';
    headline = 'מצב טוב';
    general = {
      level: 'good',
      text: remaining > 0 ? `נשארו ${remaining} לחודש הזה` : 'בתוך התקציב',
    };
  }

  return {
    category: cat,
    level,
    headline,
    effective,
    used,
    remaining,
    daysInMonth,
    dayOfMonth,
    dailyBudget: daily.value,
    dailyAuto: daily.auto,
    dailyOverridden: daily.overridden,
    allowedUntilToday,
    bank,
    todayCount,
    weekCount,
    weekStart,
    weekEnd,
    dailyExceeded,
    daily: dailyInd,
    general,
    weekly,
  };
}

export const LEVEL_RANK: Record<StatusLevel, number> = { good: 0, warning: 1, bad: 2 };

export function worstLevel(levels: StatusLevel[]): StatusLevel {
  return levels.reduce<StatusLevel>((acc, l) => (LEVEL_RANK[l] > LEVEL_RANK[acc] ? l : acc), 'good');
}

export interface DayCell {
  date: Date;
  dayKey: string;
  counts: Record<CategoryId, number>;
  /** null = nothing logged (clean day) */
  level: StatusLevel | null;
  isFuture: boolean;
}

/** Builds calendar day cells for a month with per-day color coding. */
export function buildMonthDays(data: AppData, ledger: Ledger, monthKey: string, now: Date): DayCell[] {
  const days = daysInMonthKey(monthKey);
  const { year, month } = parseMonthKey(monthKey);
  const perDay = new Map<string, Record<CategoryId, number>>();
  const allByCat: Record<CategoryId, number[]> = { cigarettes: [], joints: [], cigars: [] };
  for (const l of data.logs) {
    allByCat[l.category].push(l.timestamp);
    if (monthKeyOf(l.timestamp) !== monthKey) continue;
    const k = dayKeyOf(l.timestamp);
    let r = perDay.get(k);
    if (!r) {
      r = { cigarettes: 0, joints: 0, cigars: 0 };
      perDay.set(k, r);
    }
    r[l.category] += 1;
  }
  const cumulative: Record<CategoryId, number> = { cigarettes: 0, joints: 0, cigars: 0 };
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
  const cells: DayCell[] = [];

  for (let d = 1; d <= days; d += 1) {
    const date = new Date(year, month, d);
    const dayKey = dayKeyOf(date);
    const counts = perDay.get(dayKey) ?? { cigarettes: 0, joints: 0, cigars: 0 };
    const levels: StatusLevel[] = [];
    let any = false;
    for (const cat of CATEGORY_IDS) {
      const c = counts[cat];
      cumulative[cat] += c;
      if (c === 0) continue;
      any = true;
      const row = ledger[monthKey]?.[cat];
      const settings = data.settings[cat];
      const effective = row?.effective ?? settings.monthlyLimit;
      const daily = dailyBudgetFor(settings, effective, days).value;
      const allowed = (effective / days) * d;
      const cum = cumulative[cat];
      let lvl: StatusLevel = 'good';
      if (cum > effective) lvl = 'bad';
      else if (settings.weeklyEnabled) {
        const { start } = weekRange(date);
        const endOfDay = date.getTime() + 86_399_999;
        const wk = allByCat[cat].filter((t) => t >= start.getTime() && t <= endOfDay).length;
        if (wk > settings.weeklyLimit) lvl = 'bad';
        else if (cum === effective || wk === settings.weeklyLimit) lvl = 'warning';
      } else if (cum === effective) lvl = 'warning';
      if (lvl === 'good' && settings.focus === 'daily' && (c > daily + 1e-9 || cum > allowed + 1e-9)) {
        lvl = 'warning';
      }
      levels.push(lvl);
    }
    cells.push({
      date,
      dayKey,
      counts,
      level: any ? worstLevel(levels) : null,
      isFuture: date.getTime() > todayStart,
    });
  }
  return cells;
}

export function resultLevel(r: MonthResult): StatusLevel {
  return r === 'over' ? 'bad' : r === 'exact' ? 'warning' : 'good';
}

export const RESULT_LABEL: Record<MonthResult, string> = {
  met: 'עמד ביעד',
  exact: 'בדיוק ביעד',
  over: 'חריגה',
};
